/*
 * Service worker. SPEC.md §8 Phase 8.
 *
 * Hand-written rather than generated by Serwist, which SPEC.md §4 names. Serwist
 * hooks the *webpack* config, and `next build` in this project runs Turbopack —
 * adopting it would mean moving the whole Coolify build off Next 16's default
 * bundler for one feature. Its main job is generating a precache manifest, and
 * every route here is server-rendered on demand, so there is no static HTML to
 * precache: only content-hashed assets, which the cache-first rule below covers
 * in a few lines. Decided in Phase 8.
 *
 * Deliberately small. §10 keeps the offline surface to one table and one
 * operation, and this file should not grow past what that needs.
 */

const VERSION = "v1";
const ASSET_CACHE = `assets-${VERSION}`;
const PAGE_CACHE = `pages-${VERSION}`;
const OFFLINE_URL = "/offline";

self.addEventListener("install", (event) => {
  // The fallback is the only thing precached; everything else arrives as it is
  // used. Skip waiting so a new deploy takes effect on the next load rather
  // than whenever every tab happens to close.
  event.waitUntil(
    caches.open(PAGE_CACHE).then((cache) => cache.add(OFFLINE_URL)),
  );
  self.skipWaiting();
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    (async () => {
      // Drop caches from older versions of this file, so a deploy cannot leave
      // stale assets behind forever.
      const names = await caches.keys();
      await Promise.all(
        names
          .filter((name) => !name.endsWith(VERSION))
          .map((name) => caches.delete(name)),
      );
      await self.clients.claim();
    })(),
  );
});

self.addEventListener("fetch", (event) => {
  const request = event.request;

  // Only GET is ever cacheable, and a tick is a POST to Supabase that must
  // reach the network or fail so the app can queue it.
  if (request.method !== "GET") return;

  const url = new URL(request.url);

  // Never touch anything cross-origin: Supabase REST, auth and the realtime
  // websocket all have to go straight to the network.
  if (url.origin !== self.location.origin) return;

  // Content-hashed and immutable, so once cached it can be served without ever
  // asking again. This is what makes a cold offline start possible at all.
  if (url.pathname.startsWith("/_next/static/")) {
    event.respondWith(cacheFirst(request, ASSET_CACHE));
    return;
  }

  if (request.mode === "navigate") {
    event.respondWith(navigationWithFallback(request));
  }
});

async function cacheFirst(request, cacheName) {
  const cached = await caches.match(request);
  if (cached) return cached;

  const response = await fetch(request);
  if (response.ok) {
    const cache = await caches.open(cacheName);
    cache.put(request, response.clone());
  }
  return response;
}

/**
 * Network first, falling back to the last copy of this page, then to /offline.
 *
 * Network first rather than cache first because these pages are server-rendered
 * and personal: a cached copy is a snapshot of somebody's list and should only
 * ever be a fallback. That snapshot is why `clearOfflineData()` wipes these
 * caches on sign-out.
 */
async function navigationWithFallback(request) {
  try {
    const response = await fetch(request);
    if (response.ok) {
      const cache = await caches.open(PAGE_CACHE);
      cache.put(request, response.clone());
    }
    return response;
  } catch {
    const cached = await caches.match(request);
    if (cached) return cached;

    const offline = await caches.match(OFFLINE_URL);
    if (offline) return offline;

    return new Response("Offline", {
      status: 503,
      headers: { "Content-Type": "text/plain" },
    });
  }
}
